    for ch in k[1:]:
        if not (ch.isalpha() or ch.isdigit() or ch == '_' or ch == '$'):
            return False
    return True

def escape_json_string(s):
    # produce JSON quoted string with Go-like escaping
    res = []
    for ch in s:
        if ch == '"':
            res.append('\\"')
        elif ch == '\\':
            res.append('\\\\')
        elif ch == '\b':
            res.append('\\b')
        elif ch == '\f':
            res.append('\\f')
        elif ch == '\n':
            res.append('\\n')
        elif ch == '\r':
            res.append('\\r')
        elif ch == '\t':
            res.append('\\t')
        elif ord(ch) < 0x20:
            res.append('\\u%04X' % ord(ch))
        elif ord(ch) == 0x7F:
