            traverse(v, path, out)
            path.pop()
    elif isinstance(value, list):
        for idx, v in enumerate(value):
            path.append(idx)
            traverse(v, path, out)
            path.pop()

def format_statements(stmts, color=False, no_sort=False):
    # stmts is list of (path, value)
    # If no_sort false, sort
    # Then format each as "path = value;"
    # For root path [], left is "json"
    if not no_sort:
        stmts = sort_statements(stmts)
    lines=[]
    for path,val in stmts:
        left = colorize_left(path) if color else format_path(path)
        if color:
            right = colorize_value(val)
        else:
            right = value_to_string(val)
        lines.append(f"{left} = {right};")
    return lines

