def load_json_preserve(text):
    # strip BOM?
    # Need to handle empty
    if text.strip() == "":
        raise ValueError("EOF")
    decoder = json.JSONDecoder(object_pairs_hook=lambda pairs: dict(pairs), parse_float=lambda x: RawNumber(x), parse_int=lambda x: RawNumber(x))
    # Use raw_decode to handle trailing whitespace only
    try:
        obj, idx = decoder.raw_decode(text.strip())
        return obj
    except json.JSONDecodeError as e:
        # map to Go error
        # e.msg, e.pos, e.doc
        # If text is "notjson" then e.pos 0 char 'n'
        # Map to "invalid character 'X' looking for beginning of value"
        # Determine char at e.pos
        doc = e.doc
        pos = e.pos
        # For unterminated string etc, char may be different
        if "Expecting value" in e.msg or "Expecting property name" in e.msg or "Unterminated" in e.msg:
            if pos < len(doc):
                ch = doc[pos]
                # for unterminated string, ch is at pos maybe '"'? Not needed
                raise ValueError(f"invalid character '{ch}' looking for beginning of value")
            else:
                raise ValueError("EOF")
        # fallback
        if pos < len(doc):
            ch = doc[pos]
            raise ValueError(f"invalid character '{ch}' looking for beginning of value")
        raise ValueError(str(e))

def gron_from_json_text(text, color=False, no_sort=False, json_stream=False):
    obj = load_json_preserve(text)
    stmts=[]
    traverse(obj, [], stmts)
    if json_stream:
        return format_json_stream(stmts, color=color, no_sort=no_sort)
    else:
        return format_statements(stmts, color=color, no_sort=no_sort)

def parse_statement_line(line):
    # Parse a gron statement line like 'json.a = 1;' or 'json["a b"] = "hi";'
    # Return (path_tokens, value, raw_value_str) or None if line is not a statement (for --values skipping)
    # It should be strict for ungron but lenient for values
    # Steps: check line starts with "json"
    original = line
    stripped = line.strip()
    if stripped == "":
        raise ValueError(f"failed to parse '{original}' as gron statement")
    if not stripped.startswith("json"):
        # For values mode, silently ignore non-json lines? For ungron, treat as no statements
        return None
    # Need to find " = " separator. Original seems to allow "json.a=1;" without spaces? Values tests showed "json.a=1;" works, also "json.a =1;" etc. So "=" with optional spaces
    # Also value ends with ";"
    # Value may be after "=" up to ";"
    # Need to parse path and value
    # Find "=" position
    eq_idx = stripped.find("=")
    if eq_idx == -1:
        # no equals -> statement has no value? For ungron error "statement has no value"
        raise ValueError(f"ungron failed for `{original}`: statement has no value")
    left = stripped[:eq_idx].strip()
    right = stripped[eq_idx+1:].strip()
    # right should end with ";"
    if not right.endswith(";"):
        raise ValueError(f"ungron failed for `{original}`: statement has no value")
    # remove trailing ";"
    right_val = right[:-1].strip()
    # left should be "json" plus path suffix
    if left == "json":
        path = []
    else:
        if not left.startswith("json"):
            raise ValueError(f"failed to parse '{original}' as gron statement")
        suffix = left[4:] # after "json"
        # suffix should be like ".a" or '["a b"]' or "[0]" etc.
        # Parse tokens
        path = []
        i=0
        while i < len(suffix):
            if suffix[i] == '.':
                # bare key
                i+=1
                start=i
                while i < len(suffix) and suffix[i] not in ['.', '[']:
                    i+=1
                key = suffix[start:i]
                if key == "":
                    raise ValueError(f"failed to parse '{original}' as gron statement")
                # Validate key is bare? But we can accept any
                path.append(key)
            elif suffix[i] == '[':
                # quoted key or index
                # Find matching ]
                i+=1
                if i >= len(suffix):
                    raise ValueError(f"failed to parse '{original}' as gron statement")
                if suffix[i] == '"':
                    # quoted string
                    # parse JSON string
                    # Find closing quote with escapes
                    end = i
                    # Use json decoder to parse string?
                    # Simplified: find closing quote
                    j=i+1
                    esc=False
                    while j < len(suffix):
                        if esc:
                            esc=False
                            j+=1
                        elif suffix[j] == '\\':
                            esc=True
                            j+=1
                        elif suffix[j] == '"':
                            break
                        else:
                            j+=1
                    if j >= len(suffix) or suffix[j] != '"':
                        raise ValueError(f"failed to parse '{original}' as gron statement")
                    # Extract string literal including quotes
                    str_lit = suffix[i:j+1]
                    try:
                        key = json.loads(str_lit)
                    except:
                        raise ValueError(f"failed to parse '{original}' as gron statement")
                    # Expect closing ]
                    if j+1 >= len(suffix) or suffix[j+1] != ']':
                        raise ValueError(f"failed to parse '{original}' as gron statement")
                    path.append(key)
                    i = j+2
                else:
                    # numeric index
                    start=i
                    while i < len(suffix) and suffix[i] != ']':
                        i+=1
                    if i >= len(suffix):
                        raise ValueError(f"failed to parse '{original}' as gron statement")
                    num_str = suffix[start:i]
                    try:
                        num = int(num_str.strip())
                    except:
                        raise ValueError(f"failed to parse '{original}' as gron statement")
                    path.append(num)
                    i+=1 # skip ]
            else:
                raise ValueError(f"failed to parse '{original}' as gron statement")
    # Now right_val is value string like "1", "\"hi\"", "true", "{}", "[]"
    if right_val == "":
        raise ValueError(f"ungron failed for `{original}`: invalid value ``")
    # Parse value
    # Could be RawNumber, string, bool, null, {}, []
    try:
        # Use json decoder with RawNumber
        decoder = json.JSONDecoder(parse_float=lambda x: RawNumber(x), parse_int=lambda x: RawNumber(x))
        val, idx = decoder.raw_decode(right_val)
        # Check that idx consumes all of right_val (allow trailing whitespace? but we stripped)
        rest = right_val[idx:].strip()
        if rest != "":
            raise ValueError(f"ungron failed for `{original}`: invalid value `{right_val}`")
        # Ensure val is not something extra? For value "undefined" would fail to decode and produce invalid char error
    except json.JSONDecodeError as e:
        # Map to invalid value error
        raise ValueError(f"ungron failed for `{original}`: invalid value `{right_val}`")
    except ValueError as ve:
        # re-raise if already formatted
        if "ungron failed" in str(ve):
            raise
        raise ValueError(f"ungron failed for `{original}`: invalid value `{right_val}`")
    return (path, val, right_val)

