def build_from_statements(lines):
    # lines are list of parsed (path,val)
    # Need to reconstruct JSON. Approach: start with None, set values accordingly, merging.
    root=None
    root_set=False
    for path,val in lines:
        if not path:
            # root assignment
            if val is not None and isinstance(val, dict) and val=={}:
                # empty object
                if not root_set:
                    root={}
                    root_set=True
                else:
                    # merging? If root already exists and is not dict, error
                    if not isinstance(root, dict):
                        raise ValueError("failed to merge statements: cannot merge array with non-array")
                    # keep existing
            elif val is not None and isinstance(val, list) and val==[]:
                if not root_set:
                    root=[]; root_set=True
                else:
                    if not isinstance(root, list):
                        raise ValueError("failed to merge statements: cannot merge object with non-object")
            else:
                # primitive root
                root=val
                root_set=True
            continue
        # Ensure root exists
        if not root_set:
            # Need to infer root type based on first component? Original seems to create root as {} if first path is .key, or [] if first path is [index]
            # For gron statements, there is always an explicit "json = {}" or "json = []" before children, but if filtered, root may be missing.
            # When reconstructing filtered data, they pad arrays with null etc. So root type inference: if path[0] is int => root is list, else dict
            if isinstance(path[0], int):
                root=[]
            else:
                root={}
            root_set=True
        cur=root
        for i, tok in enumerate(path):
            is_last = (i == len(path)-1)
            nxt_tok = path[i+1] if not is_last else None
            if isinstance(tok, int):
                # need cur be list
                if not isinstance(cur, list):
                    raise ValueError("failed to merge statements: cannot merge array with non-array")
                # extend list to accommodate
                while len(cur) <= tok:
                    cur.append(None)
                if is_last:
                    cur[tok]=val
                else:
                    if cur[tok] is None:
                        # create next container based on nxt_tok type
                        if isinstance(nxt_tok, int):
                            cur[tok]=[]
                        else:
                            cur[tok]={}
                    elif cur[tok] is None:
                        pass
                    # if existing is None but need object/array, create
                    # But if existing is already a primitive, need to check merging?
                    # e.g., cur[tok] is 1 and we need to set cur[tok][...] => error
                    # For now, if cur[tok] is not dict/list when we need to go deeper, error
                    if not is_last:
                        if cur[tok] is None:
                            # already handled
                            pass
                        elif isinstance(cur[tok], (dict,list)):
                            pass
                        else:
                            # conflict
                            raise ValueError("failed to merge statements: cannot merge object with non-object")
                    cur=cur[tok]
            else: # string
                if not isinstance(cur, dict):
                    raise ValueError("failed to merge statements: cannot merge object with non-object")
                if is_last:
                    cur[tok]=val
                else:
                    if tok not in cur or cur[tok] is None:
                        if isinstance(nxt_tok, int):
                            cur[tok]=[]
                        else:
                            cur[tok]={}
                    # if existing is primitive, conflict
                    if tok in cur and not is_last:
                        if not isinstance(cur[tok], (dict,list)):
                            # if it's a primitive, but we need to go deeper, then it's an error? Original would maybe override?
                            # For example json.a = 1; json.a.b =2; This would be merging object with non-object
                            raise ValueError("failed to merge statements: cannot merge object with non-object")
                        cur=cur[tok]
                    else:
                        if not is_last:
                            cur=cur[tok]
    if not root_set:
        return None
    # Replace any remaining None in arrays with null? Actually sparse arrays should have null for missing indices. Our construction already has None for missing; when dumping, None becomes null, which matches.
    return root

def parse_statements_for_ungron(text, is_json_stream=False):
    if text.strip()=="":
        return None, "no statements were parsed"
    lines=text.splitlines()
    # For json stream mode, each line is JSON array [path, value]
    if is_json_stream:
        stmts=[]
        for line in lines:
            if line.strip()=="":
                # empty line in json stream? Original? Possibly error due to invalid char? Let's see: what does original do for empty line in json stream? It tries to parse as JSON and fails with "unexpected end of JSON input" etc.
                # For our handling, treat empty line as skip? But earlier test: json stream with empty line not present.
                # We'll treat empty line as error?
                return None, "unexpected end of JSON input"
            try:
                dec=json.JSONDecoder(parse_float=lambda x: RawNum(x), parse_int=lambda x: RawNum(x))
                arr, idx = dec.raw_decode(line.strip())
                rest=line.strip()[idx:].strip()
                if rest!="":
                    raise ValueError("invalid json")
                if not isinstance(arr, list) or len(arr)!=2:
                    return None, "json: cannot unmarshal object into Go value of type []interface {}"
                path, val = arr
                # path should be list, val is value
                stmts.append((path,val))
            except json.JSONDecodeError as e:
                # Map errors
                if "Expecting value" in e.msg:
                    # Try to get char
                    if e.pos < len(line):
                        ch=line[e.pos]
                        return None, f"invalid character '{ch}' looking for beginning of value"
                    return None, "unexpected end of JSON input"
                if "Unterminated" in e.msg:
                    return None, "unexpected end of JSON input"
                return None, str(e)
            except ValueError as ve:
                if "cannot unmarshal" in str(ve):
                    return None, str(ve)
                return None, str(ve)
        return stmts, None
    else:
        stmts=[]
        has_valid=False
        for line in lines:
            if line.strip()=="":
                continue
            # Parse strictly
            try:
                res=strict_parse(line)
                if res is None:
                    # ignore non-json lines? But for ungron, non-json lines should be considered no statements? Original for ungron with input "notvalid" gave "no statements were parsed"
                    continue
                path,val,raw=res
                stmts.append((path,val))
                has_valid=True
            except ValueError as e:
                msg=str(e)
                if "failed to parse" in msg:
                    return None, msg
                if "ungron failed" in msg:
                    return None, msg
                if msg=="panic":
                    return None, "panic"
                return None, msg
        if not has_valid:
            return None, "no statements were parsed"
        return stmts, None

def json_dumps_pretty(obj):
    # Use custom pretty printer preserving RawNum
    def helper(v, indent=0):
        ind="  "*indent
        if isinstance(v, RawNum):
            return v
        if isinstance(v, str):
            return esc(v)
        if v is True: return "true"
        if v is False: return "false"
        if v is None: return "null"
        if isinstance(v, dict):
            if not v: return "{}"
            items=[]
            for k,val in v.items():
                ks=esc(k)
                vs=helper(val, indent+1)
                items.append(f'{"  "*(indent+1)}{ks}: {vs}')
            return "{\n" + ",\n".join(items) + f"\n{ind}}}"
        if isinstance(v, list):
            if not v: return "[]"
            items=[]
            for val in v:
                vs=helper(val, indent+1)
                items.append(f'{"  "*(indent+1)}{vs}')
            return "[\n" + ",\n".join(items) + f"\n{ind}]"
        return json.dumps(v, ensure_ascii=False)
    return helper(obj,0)

