  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
"""

RESERVED = {"break","case","catch","class","const","continue","debugger","default","delete","do","else","export","extends","false","finally","for","function","if","import","in","instanceof","new","null","return","super","switch","this","throw","true","try","typeof","var","void","while","with","yield"}

def is_bare(k):
    if k == "" or k in RESERVED:
        return False
    if not k:
        return False
    f = k[0]
    if not (f.isalpha() or f == '_' or f == '$'):
        return False
    for c in k[1:]:
        if not (c.isalpha() or c.isdigit() or c == '_' or c == '$'):
            return False
    return True

def esc(s):
    out=[]
    for ch in s:
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\b': out.append('\\b')
        elif ch == '\f': out.append('\\f')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif ord(ch) < 0x20: out.append('\\u%04X' % ord(ch))
        elif ord(ch) == 0x7F: out.append('\\u007F')
        elif ch == '\u2028': out.append('\\u2028')
        elif ch == '\u2029': out.append('\\u2029')
        else: out.append(ch)
    return '"' + ''.join(out) + '"'

class RawNum(str):
    pass

def fmt_path(p):
    out="json"
    for tok in p:
        if isinstance(tok, int):
            out+=f"[{tok}]"
        else:
            if is_bare(tok):
                out+=f".{tok}"
            else:
                out+=f"[{esc(tok)}]"
    return out

def val_str(v):
    if isinstance(v, RawNum): return v
    if isinstance(v, str): return esc(v)
    if v is True: return "true"
    if v is False: return "false"
    if v is None: return "null"
    if isinstance(v, dict): return "{}"
    if isinstance(v, list): return "[]"
    return json.dumps(v, ensure_ascii=False)

def c_left(p):
    BLUE="\x1b[34;1m"; BR="\x1b[0;22m"; MAG="\x1b[35m"; RST="\x1b[0m"; YEL="\x1b[33m"; RED="\x1b[31m"
    out=BLUE+"json"+BR
    for tok in p:
        if isinstance(tok,int):
            out+=MAG+"["+RST+RED+str(tok)+RST+MAG+"]"+RST
        else:
            if is_bare(tok):
                out+="."+BLUE+tok+BR
            else:
                out+=MAG+"["+RST+YEL+esc(tok)+RST+MAG+"]"+RST
    return out

def c_val(v):
    RED="\x1b[31m"; YEL="\x1b[33m"; CYN="\x1b[36m"; MAG="\x1b[35m"; RST="\x1b[0m"
    s=val_str(v)
    if isinstance(v, RawNum): return RED+s+RST
    if isinstance(v, str): return YEL+s+RST
    if v is True or v is False or v is None: return CYN+s+RST
    if isinstance(v,(dict,list)): return MAG+s+RST
    return s

def cmp_path(a,b):
    for i in range(min(len(a),len(b))):
        x=a[i]; y=b[i]
        if x==y: continue
        if isinstance(x,int) and isinstance(y,int):
            return -1 if x<y else 1
        if isinstance(x,str) and isinstance(y,str):
            return -1 if x<y else 1
        if isinstance(x,int): return -1
        return 1
    return -1 if len(a)<len(b) else (1 if len(a)>len(b) else 0)

def sort_stmts(s):
    return sorted(s, key=functools.cmp_to_key(lambda a,b: cmp_path(a[0],b[0])))

def traverse(v,path,out):
    out.append((list(path),v))
    if isinstance(v,dict):
        for k,val in v.items():
            path.append(k); traverse(val,path,out); path.pop()
    elif isinstance(v,list):
        for i,val in enumerate(v):
            path.append(i); traverse(val,path,out); path.pop()

def fmt_stmts(stmts,color=False,no_sort=False):
    if not no_sort: stmts=sort_stmts(stmts)
    lines=[]
    for p,v in stmts:
        left=c_left(p) if color else fmt_path(p)
        right=c_val(v) if color else val_str(v)
        lines.append(f"{left} = {right};")
    return lines

def fmt_json_stream(stmts,color=False,no_sort=False):
    if not no_sort: stmts=sort_stmts(stmts)
    lines=[]
    for p,v in stmts:
        pj=json.dumps(p, ensure_ascii=False)
        if isinstance(v,RawNum): vj=str(v)
        elif isinstance(v,str): vj=esc(v)
        elif v is True: vj="true"
        elif v is False: vj="false"
        elif v is None: vj="null"
        elif isinstance(v,dict): vj="{}"
        elif isinstance(v,list): vj="[]"
        else: vj=json.dumps(v, ensure_ascii=False)
        raw=f"[{pj},{vj}]"
        if color:
            # colorize raw JSON line: brackets magenta, strings yellow, numbers red, booleans cyan
            def color_json(s):
                res=""; i=0
                while i < len(s):
                    c=s[i]
                    if c in "[],":
                        res+="\x1b[35m"+c+"\x1b[0m"; i+=1
                    elif c=='"':
                        j=i+1; esc2=False
                        while j < len(s):
                            if esc2: esc2=False; j+=1
                            elif s[j]=='\\': esc2=True; j+=1
                            elif s[j]=='"': break
                            else: j+=1
                        j+=1
                        res+="\x1b[33m"+s[i:j]+"\x1b[0m"; i=j
                    elif s.startswith("true",i):
                        res+="\x1b[36mtrue\x1b[0m"; i+=4
                    elif s.startswith("false",i):
                        res+="\x1b[36mfalse\x1b[0m"; i+=5
                    elif s.startswith("null",i):
                        res+="\x1b[36mnull\x1b[0m"; i+=4
                    elif c=='{' or c=='}':
                        res+="\x1b[35m"+c+"\x1b[0m"; i+=1
                    elif c.isdigit() or c=='-' or c=='.':
                        j=i
                        while j < len(s) and s[j] in "0123456789.-+eE":
                            j+=1
                        res+="\x1b[31m"+s[i:j]+"\x1b[0m"; i=j
                    else:
                        res+=c; i+=1
                return res
            lines.append(color_json(raw))
        else:
            lines.append(raw)
    return lines

def parse_json(text):
    if text.strip()=="":
        raise ValueError("EOF")
    dec=json.JSONDecoder(object_pairs_hook=lambda pairs: dict(pairs), parse_float=lambda x: RawNum(x), parse_int=lambda x: RawNum(x))
    try:
