                else:
                    raise ValueError(f"invalid character '{ch}' looking for beginning of value")
            raise ValueError(f"invalid character '{ch}' looking for beginning of value")
        raise ValueError(str(e))

def gron_lines(text,color=False,no_sort=False,json_stream=False):
    obj=parse_json(text)
    stmts=[]
    traverse(obj,[],stmts)
    if json_stream:
        return fmt_json_stream(stmts,color,no_sort)
    else:
        return fmt_stmts(stmts,color,no_sort)

# Parsing statements for ungron / values
def parse_path_suffix(suffix, original):
    path=[]
    i=0
    while i < len(suffix):
        if suffix[i]=='.':
            i+=1
            start=i
            while i < len(suffix) and suffix[i] not in ".[": 
                i+=1
            key=suffix[start:i]
            if key=="":
                raise ValueError(f"failed to parse '{original}' as gron statement")
            path.append(key)
        elif suffix[i]=='[':
            i+=1
            if i>=len(suffix):
                raise ValueError(f"failed to parse '{original}' as gron statement")
            if suffix[i]=='"':
                j=i+1; esc2=False
                while j < len(suffix):
                    if esc2: esc2=False; j+=1
                    elif suffix[j]=='\\': esc2=True; j+=1
                    elif suffix[j]=='"': break
                    else: j+=1
                if j>=len(suffix) or suffix[j]!='"':
                    raise ValueError(f"failed to parse '{original}' as gron statement")
                lit=suffix[i:j+1]
                try: key=json.loads(lit)
                except: raise ValueError(f"failed to parse '{original}' as gron statement")
                if j+1>=len(suffix) or suffix[j+1]!=']':
                    raise ValueError(f"failed to parse '{original}' as gron statement")
                path.append(key)
                i=j+2
            else:
                start=i
                while i < len(suffix) and suffix[i]!=']': i+=1
                if i>=len(suffix):
                    raise ValueError(f"failed to parse '{original}' as gron statement")
                num=suffix[start:i]
                try: n=int(num.strip())
                except: raise ValueError(f"failed to parse '{original}' as gron statement")
                path.append(n)
                i+=1
        else:
            raise ValueError(f"failed to parse '{original}' as gron statement")
    return path

def flexible_parse(line):
    orig=line
    stripped=line.strip()
    if not stripped.startswith("json"):
        return None
    if stripped=="json":
        # panic case for values?
        raise ValueError("panic")
    eq=stripped.find("=")
    if eq==-1:
        raise ValueError(f"ungron failed for `{orig}`: statement has no value")
    left=stripped[:eq].strip()
    right=stripped[eq+1:].strip()
    # Find ;. If present, handle; else for values we treat whole rest as value, for ungron require ;
    semi=right.find(";")
    if semi!=-1:
