        rest=raw[idx:].strip()
        if rest!="":
            raise ValueError(f"ungron failed for `{orig}`: invalid value `{raw}`")
    except json.JSONDecodeError as e:
        raise ValueError(f"ungron failed for `{orig}`: invalid value `{raw}`")
    return (path,val,raw,has_semi)

def strict_parse(line):
    orig=line
    stripped=line.strip()
    if stripped=="":
        raise ValueError(f"failed to parse '{orig}' as gron statement")
    if not stripped.startswith("json"):
