    eq=stripped.find("=")
    if eq==-1:
        raise ValueError(f"ungron failed for `{orig}`: statement has no value")
    left=stripped[:eq].strip()
    right=stripped[eq+1:].strip()
    if not right.endswith(";"):
        raise ValueError(f"ungron failed for `{orig}`: statement has no value")
