    if left=="json":
        path=[]
    else:
        if not left.startswith("json"):
            raise ValueError(f"failed to parse '{orig}' as gron statement")
        suffix=left[4:]
        path=parse_path_suffix(suffix, orig)
    if raw=="":
        raise ValueError(f"ungron failed for `{orig}`: invalid value ``")
    dec=json.JSONDecoder(parse_float=lambda x: RawNum(x), parse_int=lambda x: RawNum(x))
    try:
        val, idx = dec.raw_decode(raw)
        rest=raw[idx:].strip()
        if rest!="":
            raise ValueError(f"ungron failed for `{orig}`: invalid value `{raw}`")
    except json.JSONDecodeError:
        raise ValueError(f"ungron failed for `{orig}`: invalid value `{raw}`")
    return (path,val,raw)

def do_values(text):
    if text=="":
        return [], None
    lines=text.splitlines()
    # empty text already handled
    out=[]
    for line in lines:
        # check whitespace line
        if line.strip()=="" :
            # line is empty or whitespace
            # For splitlines, "" corresponds to empty line; "   " corresponds to whitespace line
            # Both should error, but need to differentiate message: they include the line content as is (original line without stripping? Actually error message includes the line content as is? For "   " error shows "'   '", for "" shows "''". So we use line as is (line without newline, keep as is))
            return None, f"failed to parse '{line}' as gron statement"
        if not line.strip().startswith("json"):
